// 中身でファイル名が決まるもの：フォント、文字の CSS（fonts-<hash>.css。KEEP にも入る）、キャラの絵
const IMMUTABLE = /\/fonts\/[0-9a-f]+\.woff2$|\/fonts-[0-9a-f]{10}\.css$|\/art\/[a-z]+-[a-z]+-[0-9a-f]{10}\.webp$/;

self.addEventListener('install', e => {
  // cache:'reload' で HTTP キャッシュ（GitHub Pages は10分）を通さず、必ずこの版のファイルを控える
  e.waitUntil(Promise.all([
    caches.open(CORE).then(c => c.addAll(FILES.map(f => new Request(f, { cache: 'reload' })))),
    caches.open(STATIC).then(c => Promise.all(KEEP.map(f => c.match(f).then(hit => hit || c.add(f)))))
  ]).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  const keep = new Set(KEEP.map(f => new URL(f, location.href).href));
  const fonts = new Set(FONTS.map(f => new URL(f, location.href).href));
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => (k.startsWith('tabicho-core-') && k !== CORE) || k === 'tabicho-runtime' || (k.startsWith('tabicho-tiles-') && k !== TILES)).map(k => caches.delete(k))))
    // 控え（STATIC）から、今の版が使わなくなった絵・文字の CSS・フォントを消す
    .then(() => caches.open(STATIC)).then(c => c.keys().then(ks => Promise.all(ks.filter(k => ((/\/art\//.test(k.url) || /\/fonts-[0-9a-f]{10}\.css$/.test(k.url)) && !keep.has(k.url)) || (fonts.size && /\/fonts\/[^/]+\.woff2$/.test(k.url) && !fonts.has(k.url))).map(k => c.delete(k)))))
    .catch(() => {})
    .then(() => self.clients.claim()));
});

// 地図画像: CORS で取れたもの（中身の状態が分かるもの）だけ、新しい順に TILE_MAX 枚まで控える
const noCors = {};
let puts = 0;
async function tile(e, req, host) {
  const c = await caches.open(TILES);
  const hit = await c.match(req.url);
  if (hit) return hit;
  let res = null;
  if (!noCors[host]) try { res = await fetch(req.url, { mode: 'cors', credentials: 'omit', referrerPolicy: 'strict-origin' }); } catch (err) { res = null; }
  if (!res) {
    // CORS を返さない地図サーバーのときは、これまでどおり <img> の要求をそのまま通す（控えない）
    const r = await fetch(req);
    if (r.type === 'opaque') noCors[host] = true;
    return r;
  }
  if (res.ok) e.waitUntil(c.put(req.url, res.clone())
    .then(() => (puts++ % 25) ? null : c.keys().then(ks => Promise.all(ks.slice(0, Math.max(0, ks.length - TILE_MAX)).map(k => c.delete(k)))))
    .catch(() => {}));
  return res;
}

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin === location.origin) {
    // フォントと絵（中身でファイル名が決まる）: 一度取れば、版が替わっても使い回す
    if (IMMUTABLE.test(url.pathname)) {
      e.respondWith(caches.open(STATIC).then(c => c.match(req).then(hit => hit || fetch(req).then(res => { if (res.ok) c.put(req, res.clone()); return res; }))));
      return;
    }
    // 本体: ネットにつながれば最新を取る。電波が弱くて待っても来ないときは、端末の控えを先に出す
    const nav = req.mode === 'navigate';
    let put = null;
    const net = fetch(req).then(res => { if (res.ok) { const copy = res.clone(); put = caches.open(CORE).then(c => c.put(req, copy)); } return res; });
    e.waitUntil(net.then(() => put, () => {}).catch(() => {}));
    // 控えが無いとき、ページを開く要求だけ index.html で答える（フォントや JS に HTML を返さない）
    const fromCache = () => caches.match(req, { ignoreSearch: true }).then(r => r || (nav ? caches.match('./index.html') : undefined));
    e.respondWith(new Promise(resolve => {
      let done = false; const give = r => { if (!done && r) { done = true; resolve(r); } };
      const t = setTimeout(() => fromCache().then(give, () => {}), WAIT_MS);
      net.then(r => {
        clearTimeout(t);
        if (r.ok || !nav) give(r); else fromCache().then(c => give(c || r), () => give(r)); // 公開の入れ替え中の 404 などは控えを出す
      }, () => { clearTimeout(t); fromCache().then(r => give(r || Response.error()), () => give(Response.error())); });
    }));
    return;
  }
  // 「くわしい地図」の地図画像
  if (/(^|\.)cyberjapandata\.gsi\.go\.jp$|^tile\.openstreetmap\.org$/.test(url.hostname)) e.respondWith(tile(e, req, url.hostname));
});
